input.content:
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.getByRole('button', { name: /Cindercub/ }).click();
await page.waitForTimeout(250);
const started = await page.locator('#start-screen').evaluate(el => el.classList.contains('dismissed'));
if (!started) throw new Error('Starter selection did not begin the game');
const directions = ['down','down','down','right','right'];
for (const dir of directions) { await page.keyboard.press(({up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'})[dir]); await page.waitForTimeout(170); }
let encounter = false;
for (let i=0; i<24 && !encounter; i++) {
  const dir = ['right','down','left','up'][i%4];
  await page.keyboard.press(({up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'})[dir]);
  await page.waitForTimeout(220);
  encounter = await page.locator('#battle-panel').evaluate(el => !el.classList.contains('hidden'));
}
if (!encounter) throw new Error('No wild encounter appeared after traversing the tall grass');
const wild = await page.locator('#wild-name').textContent();
for (let i=0; i<3; i++) {
  await page.locator('#attack-btn').click();
  await page.waitForTimeout(1000);
  const visible = await page.locator('#battle-panel').evaluate(el => !el.classList.contains('hidden'));
  if (!visible) break;
  const hpText = await page.locator('#wild-hp-label').textContent();
  const values = hpText.match(/HP (\d+) \/ (\d+)/);
  if (values && Number(values[1]) <= Number(values[2]) * .55) {
    await page.locator('#capture-btn').click();
    await page.waitForTimeout(1100);
    if (await page.locator('#battle-panel').evaluate(el => el.classList.contains('hidden'))) break;
  }
}
if (!await page.locator('#battle-panel').evaluate(el => el.classList.contains('hidden'))) {
  await page.locator('#run-btn').click();
  await page.waitForTimeout(600);
}
await page.waitForTimeout(300);
const partyCount = await page.locator('#party-count').textContent();
const dims = await page.locator('#game').evaluate(el => ({ width: el.width, height: el.height, cssWidth: el.clientWidth }));
mkdirSync('/tmp/opencode', { recursive: true });
await page.screenshot({ path: '/tmp/opencode/redwood-final.jpg', type: 'jpeg', quality: 88 });
console.log(JSON.stringify({ started, encounter, wild, partyCount, canvas: dims, errors }, null, 2));
await browser.close();
if (errors.length) process.exitCode = 1;

