import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });
await page.addInitScript(() => { Math.random = () => 0; });
await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
await page.getByRole('button', { name: /Cindercub/ }).click();
await page.waitForTimeout(250);
const started = await page.locator('#start-screen').evaluate(el => el.classList.contains('dismissed'));
const key = {up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'};
async function move(dir) { await page.keyboard.press(key[dir]); await page.waitForTimeout(220); }
for (const dir of ['down','down','down','right','right','right']) await move(dir);
async function handleEncounter() {
  await page.waitForFunction(() => !document.querySelector('#battle-panel').classList.contains('hidden'), { timeout: 5000 });
  const wild = await page.locator('#wild-name').textContent();
  await page.locator('#attack-btn').click();
  await page.waitForTimeout(750);
  await page.locator('#capture-btn').click();
  await page.waitForTimeout(1100);
  if (!await page.locator('#battle-panel').evaluate(el => el.classList.contains('hidden'))) throw new Error('Encounter did not end after capture');
  return wild;
}
const firstWild = await handleEncounter();
for (let i=0;i<4;i++) await move('right');
const secondWild = await handleEncounter();
const caught = await page.locator('#caught-count').textContent();
for (let i=0;i<5;i++) await move('left');
for (let i=0;i<3;i++) await move('up');
await page.keyboard.press('e');
await page.waitForTimeout(250);
const badges = await page.locator('#badge-count').textContent();
const quest = await page.locator('#quest-title').textContent();
const partyCount = await page.locator('#party-count').textContent();
const canvas = await page.locator('#game').evaluate(el => ({ width: el.width, height: el.height, cssWidth: el.clientWidth }));
mkdirSync('/tmp/opencode', { recursive: true });
await page.screenshot({ path: '/tmp/opencode/redwood-final.jpg', type: 'jpeg', quality: 88 });
console.log(JSON.stringify({ started, firstWild, secondWild, caught, partyCount, badges, quest, canvas, errors }, null, 2));
await browser.close();
if (!started || Number(caught) < 3 || !badges.startsWith('01') || errors.length) process.exitCode = 1;

